import networkx as nx
G = nx.Graph()
for i in range(9):
    for j in range(i+1, 9):
        G.add_edge(i, j)
max_independent_set = nx.algorithms.approximation.max_weight_clique(G, weight=None)
if len(max_independent_set) <= 4:
    vertex_connectivity = nx.algorithms.connectivity.vertex_connectivity(G)
    if vertex_connectivity >= 4:
        print("SATISFIABLE")
        print(list(G.edges))
    else:
        print("UNSATISFIABLE")
else:
    print("UNSATISFIABLE")
